package com.keepcalm.placementportal.controller;import com.keepcalm.placementportal.api.PagedResponse;import com.keepcalm.placementportal.enums.OfferStatus;import com.keepcalm.placementportal.models.offer.OfferDtos.*;import com.keepcalm.placementportal.service.OfferService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.Map;
public final class OfferController{private OfferController(){}@RestController@RequestMapping("/api/v1/students/me/offers")@RequiredArgsConstructor public static class StudentOffers{private final OfferService service;@GetMapping public PagedResponse<OfferDto> list(@PageableDefault(size=20,sort="offeredAt",direction=Sort.Direction.DESC)Pageable p){return service.mine(p);}@GetMapping("/{offerId}")public OfferDto get(@PathVariable Long offerId){return service.mine(offerId);}@PostMapping("/{offerId}/accept")public OfferDto accept(@PathVariable Long offerId){return service.accept(offerId);}@PostMapping("/{offerId}/decline")public OfferDto decline(@PathVariable Long offerId){return service.decline(offerId);}}@RestController@RequestMapping("/api/v1/admin/offers")@RequiredArgsConstructor public static class AdminOffers{private final OfferService service;@GetMapping public PagedResponse<OfferDto> list(@RequestParam(required=false)OfferStatus status,@RequestParam(required=false)Long companyId,@PageableDefault(size=20)Pageable p){return service.adminList(status,companyId,p);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public OfferDto create(@Valid@RequestBody Upsert r){return service.create(r);}@PutMapping("/{offerId}")public OfferDto update(@PathVariable Long offerId,@Valid@RequestBody Upsert r){return service.update(offerId,r);}@PostMapping(value="/import",consumes="multipart/form-data")public Map<String,Object> importOffers(@RequestPart("file")MultipartFile file,@RequestHeader("Idempotency-Key")String key){return service.importOffers(file,key);}}}
